class QueryError extends Error {
  constructor(message        ) {
    super(message);
    this.name = "QueryError";
  }
}

const fail = (message        )        => { throw new QueryError(message); };
const AST_KEYS = ["from", "scope", "where", "groupBy", "aggregates", "select", "orderBy", "limit", "offset"];
const NAME = /^[A-Za-z_][A-Za-z0-9_]*$/;
const MAX_IN = 1000;

function deepFreeze   (v   )    {
  if (v !== null && typeof v === "object" && !Object.isFrozen(v)) {
    for (const k of Object.keys(v)) deepFreeze((v                           )[k]);
    Object.freeze(v);
  }
  return v;
}

function isJson(v         , depth = 0)          {
  if (depth > 64) return false;
  if (v === null || typeof v === "boolean" || typeof v === "string") return true;
  if (typeof v === "number") return Number.isFinite(v);
  if (Array.isArray(v)) return v.every((x) => isJson(x, depth + 1));
  if (typeof v === "object") return Object.keys(v          ).every((k) => isJson((v                           )[k], depth + 1));
  return false;
}

/** JSON equality: numbers by value, objects regardless of key order, true is not 1. */
function jsonEqual(a         , b         )          {
  if (a === b) return true;
  if (a === null || b === null || typeof a !== "object" || typeof b !== "object") return false;
  if (Array.isArray(a)) {
    if (!Array.isArray(b) || a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) if (!jsonEqual(a[i], b[i])) return false;
    return true;
  }
  if (Array.isArray(b)) return false;
  const ka = Object.keys(a), kb = Object.keys(b);
  if (ka.length !== kb.length) return false;
  for (const k of ka) if (!Object.prototype.hasOwnProperty.call(b, k) || !jsonEqual((a                           )[k], (b                           )[k])) return false;
  return true;
}

/** Strings compare by code point (as in SQL with the C collation, and in Python). */
function cmpStr(a        , b        )         {
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i++) {
    const x = a.codePointAt(i)          , y = b.codePointAt(i)          ;
    if (x !== y) return x < y ? -1 : 1;
    if (x > 0xffff) i++;
  }
  return a.length < b.length ? -1 : a.length > b.length ? 1 : 0;
}

function cmpValue(x         , y         )         {
  if (typeof x === "string") return cmpStr(x, y          );
  if (typeof x === "boolean") return (x ? 1 : 0) - (y ? 1 : 0);
  return (x          ) < (y          ) ? -1 : (x          ) > (y          ) ? 1 : 0;
}

/** Sort rows by `order` (nulls last either way). The sort is stable, so ties keep the rows' order. */
function sortRows   (rows     , order                  )      {
  return rows.sort((a, b) => {
    for (const o of order) {
      const x = (a                           )[o.field], y = (b                           )[o.field];
      if (x === y) continue;
      if (x === null || x === undefined) return 1;
      if (y === null || y === undefined) return -1;
      const c = cmpValue(x, y);
      if (c !== 0) return o.dir === "desc" ? -c : c;
    }
    return 0;
  });
}

function entityInfo(name        )             {
  return Object.prototype.hasOwnProperty.call(SCHEMA.entities, name) ? SCHEMA.entities[name              ] : fail(`unknown entity "${name}" (use ${Object.keys(SCHEMA.entities).join(", ")})`);
}

function fieldInfo(e            , name        , what        )            {
  return e.fields.find((f) => f.name === name) ?? fail(`${what}: unknown field "${name}"`);
}

function checkValue(f           , v         , what        )       {
  if (v === null || v === undefined) fail(`${what}: the value can't be null (use isNull)`);
  const ok = f.type === "int" ? Number.isSafeInteger(v)
    : f.type === "float" ? typeof v === "number" && Number.isFinite(v)
      : f.type === "bool" ? typeof v === "boolean"
        : f.type === "str" ? typeof v === "string"
          : isJson(v);
  if (!ok) fail(`${what}: ${JSON.stringify(v)?.slice(0, 40)} isn't ${f.type === "int" ? "an int" : f.type === "json" ? "JSON" : `a ${f.type}`}`);
}

/** Check a query against the schema, and fill in the defaults. Throws QueryError. */
function validate(input     )      {
  if (input === null || typeof input !== "object" || Array.isArray(input)) fail("a query must be an object");
  for (const k of Object.keys(input)) if (!AST_KEYS.includes(k)) fail(`unknown query key "${k}"`);
  const e = entityInfo(input.from);
  const out                                         = { from: input.from };
  if (input.scope !== undefined && input.scope !== null) {
    if (!Object.prototype.hasOwnProperty.call(e.scopes, input.scope)) fail(`${input.from} has no scope "${input.scope}" (${Object.keys(e.scopes).join(", ") || "none"})`);
    out.scope = input.scope;
  }
  if (input.where !== undefined) {
    if (!Array.isArray(input.where)) fail("where must be a list");
    out.where = input.where.map((c, i) => {
      const what = `where[${i}]`;
      if (c === null || typeof c !== "object") fail(`${what} must be {field, op, value}`);
      const f = fieldInfo(e, c.field, what);
      if (!SCHEMA.types[f.type].ops.includes(c.op)) fail(`${what}: ${f.name} (${f.type}) takes ${SCHEMA.types[f.type].ops.join(", ")}, not "${c.op}"`);
      if (c.op === "isNull") { if (typeof c.value !== "boolean") fail(`${what}: isNull takes true or false`); }
      else if (c.op === "in") {
        if (!Array.isArray(c.value) || c.value.length === 0 || c.value.length > MAX_IN) fail(`${what}: in takes a list of 1 to ${MAX_IN} values`);
        (c.value             ).forEach((v) => checkValue(f, v, what));
      } else if (c.op === "between") {
        if (!Array.isArray(c.value) || c.value.length !== 2) fail(`${what}: between takes [low, high]`);
        (c.value             ).forEach((v) => checkValue(f, v, what));
      } else checkValue(f, c.value, what);
      return { field: f.name, op: c.op, value: c.value };
    });
  }
  const names = new Set        ();
  if (input.groupBy !== undefined) {
    if (!Array.isArray(input.groupBy)) fail("groupBy must be a list");
    out.groupBy = input.groupBy.map((g) => {
      const f = fieldInfo(e, g, "groupBy");
      if (!SCHEMA.types[f.type].group) fail(`groupBy: ${f.name} (${f.type}) can't be grouped by`);
      if (names.has(f.name)) fail(`groupBy: ${f.name} twice`);
      names.add(f.name);
      return f.name;
    });
  }
  if (input.aggregates !== undefined) {
    if (!Array.isArray(input.aggregates)) fail("aggregates must be a list");
    out.aggregates = input.aggregates.map((a, i) => {
      const what = `aggregates[${i}]`;
      if (a === null || typeof a !== "object" || !["count", "sum", "avg", "min", "max"].includes(a.fn)) fail(`${what}: fn must be count, sum, avg, min or max`);
      let field                    ;
      if (a.field !== undefined && a.field !== null) {
        const f = fieldInfo(e, a.field, what);
        if (!SCHEMA.types[f.type].aggregates.includes(a.fn)) fail(`${what}: ${a.fn} doesn't apply to ${f.name} (${f.type})`);
        field = f.name;
      } else if (a.fn !== "count") fail(`${what}: ${a.fn} needs a field`);
      const as = a.as ?? (field ? `${a.fn}_${field}` : a.fn);
      if (typeof as !== "string" || !NAME.test(as) || as.length > 63) fail(`${what}: "${as}" isn't a valid name`);
      if (names.has(as)) fail(`${what}: the name "${as}" is taken`);
      names.add(as);
      return field === undefined ? { fn: a.fn, as } : { fn: a.fn, field, as };
    });
  }
  const grouped = out.groupBy !== undefined || out.aggregates !== undefined;
  if (input.select !== undefined) {
    if (grouped) fail("select can't be combined with groupBy or aggregates");
    if (!Array.isArray(input.select) || input.select.length === 0) fail("select takes a list of fields");
    const seen = new Set        ();
    out.select = input.select.map((s) => {
      const f = fieldInfo(e, s, "select");
      if (seen.has(f.name)) fail(`select: ${f.name} twice`);
      seen.add(f.name);
      return f.name;
    });
  }
  if (input.orderBy !== undefined) {
    if (!Array.isArray(input.orderBy)) fail("orderBy must be a list");
    out.orderBy = input.orderBy.map((o, i) => {
      const what = `orderBy[${i}]`;
      if (o === null || typeof o !== "object") fail(`${what} must be {field, dir}`);
      const dir = o.dir ?? "asc";
      if (dir !== "asc" && dir !== "desc") fail(`${what}: dir must be asc or desc`);
      if (grouped) { if (!names.has(o.field)) fail(`${what}: order a grouped query by its group fields or aggregates, not "${o.field}"`); }
      else {
        const f = fieldInfo(e, o.field, what);
        if (!SCHEMA.types[f.type].order) fail(`${what}: ${f.name} (${f.type}) can't be sorted`);
      }
      return { field: o.field, dir };
    });
  }
  for (const k of ["limit", "offset"]         ) {
    const v = input[k];
    if (v === undefined || v === null) continue;
    if (!Number.isSafeInteger(v) || v < 0) fail(`${k} must be a whole number ≥ 0`);
    out[k] = v;
  }
  return deepFreeze(out);
}

